    return True

def count_polite_representations(n):
    count = 0
    k = 2
    while k * (k - 1) // 2 < n:
        numerator = n - k * (k - 1) // 2
        if numerator > 0 and numerator % k == 0:
            count += 1
        k += 1
    return count

