def is_valid_coupon_code(s):
    if len(s) != 8:
        return False
    has_letter = False
    has_digit = False
    for ch in s:
        if 'A' <= ch <= 'Z':
            has_letter = True
        elif ch.isdigit():
            has_digit = True
        else:
            return False
    return has_letter and has_digit

