def count_max_nesting_depth(s):
    openers = {'(', '[', '{'}
    closers = {')', ']', '}'}
    depth = 0
    max_depth = 0
    for ch in s:
        if ch in openers:
            depth += 1
            max_depth = max(max_depth, depth)
        elif ch in closers:
            depth = max(0, depth - 1)
    return max_depth

