def year_progress_percentage(year, month, day):
    month_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)
    if leap:
        month_days[1] = 29
    days_before = 0
    for i in range(month - 1):
        days_before += month_days[i]
    day_of_year = days_before + day
    total_days = 366 if leap else 365
    return round(day_of_year / total_days * 100, 2)

